import './style.css'
import { mat4 } from 'gl-matrix'
import type { NbtCompound, Resources } from 'deepslate'
import {
	BlockDefinition,
	BlockModel,
	NbtFile,
	NbtType,
	Structure,
	StructureRenderer,
	TextureAtlas,
	upperPowerOfTwo,
} from 'deepslate'
import { strToU8, zipSync } from 'fflate'

// Generated by scripts/generate-assets.mjs — vanilla assets merged with
// anything found in modset/. Equals the vanilla set when modset/ is empty.
const MERGED_ASSETS = '/assets/merged/'

// Keys in the generated JSON are bare paths for vanilla (e.g. "stone") and
// full "namespace:path" identifiers for anything merged in from modset/.
function toFullId(id: string): string {
	return id.includes(':') ? id : `minecraft:${id}`
}
const canvas = document.getElementById('canvas') as HTMLCanvasElement
const viewport = document.getElementById('viewport') as HTMLDivElement
const dropzone = document.getElementById('dropzone') as HTMLDivElement
const fileInput = document.getElementById('file-input') as HTMLInputElement
const statusEl = document.getElementById('status') as HTMLDivElement
const gridToggle = document.getElementById('grid-toggle') as HTMLInputElement
const invisibleToggle = document.getElementById('invisible-toggle') as HTMLInputElement
const datapackNameInput = document.getElementById('datapack-name') as HTMLInputElement
const datapackDescriptionInput = document.getElementById('datapack-description') as HTMLTextAreaElement
const namespaceInput = document.getElementById('namespace') as HTMLInputElement
const structureIdInput = document.getElementById('structure-id') as HTMLInputElement
const buildNameInput = document.getElementById('build-name') as HTMLInputElement
const creatorInput = document.getElementById('creator') as HTMLInputElement
const titleColorInput = document.getElementById('title-color') as HTMLInputElement
const ingredientList = document.getElementById('ingredient-list') as HTMLDivElement
const addIngredientButton = document.getElementById('add-ingredient') as HTMLButtonElement
const downloadBtn = document.getElementById('download-btn') as HTMLButtonElement
const previewBtn = document.getElementById('preview-btn') as HTMLButtonElement
const playerModeToggle = document.getElementById('player-mode-toggle') as HTMLInputElement
const pendingFileNameEl = document.getElementById('pending-file-name') as HTMLDivElement

const gl = canvas.getContext('webgl')
if (!gl) {
	throw new Error('WebGL is not supported in this browser')
}

function setStatus(message: string, isError = false) {
	statusEl.textContent = message
	statusEl.classList.toggle('error', isError)
}

// === Load block/model/texture resources from the generated local assets ===

setStatus('Loading block resources…')

const resourcesPromise: Promise<Resources> = Promise.all([
	fetch(`${MERGED_ASSETS}block_definitions.json`).then(r => r.json()),
	fetch(`${MERGED_ASSETS}models.json`).then(r => r.json()),
	fetch(`${MERGED_ASSETS}atlas.json`).then(r => r.json()),
	new Promise<HTMLImageElement>((resolve, reject) => {
		const image = new Image()
		image.onload = () => resolve(image)
		image.onerror = () => reject(new Error('Failed to load texture atlas image'))
		image.crossOrigin = 'Anonymous'
		image.src = `${MERGED_ASSETS}atlas.png`
	}),
]).then(([blockstates, models, uvMap, atlas]) => {
	const blockDefinitions: Record<string, BlockDefinition> = {}
	Object.keys(blockstates).forEach(id => {
		blockDefinitions[toFullId(id)] = BlockDefinition.fromJson(blockstates[id])
	})

	const blockModels: Record<string, BlockModel> = {}
	Object.keys(models).forEach(id => {
		blockModels[toFullId(id)] = BlockModel.fromJson(models[id])
	})
	Object.values(blockModels).forEach(m => m.flatten({ getBlockModel: id => blockModels[id.toString()] }))

	const atlasCanvas = document.createElement('canvas')
	const atlasSize = upperPowerOfTwo(Math.max(atlas.width, atlas.height))
	atlasCanvas.width = atlasSize
	atlasCanvas.height = atlasSize
	const atlasCtx = atlasCanvas.getContext('2d')!
	atlasCtx.drawImage(atlas, 0, 0)
	const atlasData = atlasCtx.getImageData(0, 0, atlasSize, atlasSize)
	const idMap: Record<string, [number, number, number, number]> = {}
	Object.keys(uvMap).forEach(id => {
		const [u, v, du, dv] = uvMap[id]
		const dv2 = (du !== dv && id.startsWith('block/')) ? du : dv
		idMap[toFullId(id)] = [u / atlasSize, v / atlasSize, (u + du) / atlasSize, (v + dv2) / atlasSize]
	})
	const textureAtlas = new TextureAtlas(atlasData, idMap)

	const resources: Resources = {
		getBlockDefinition(id) { return blockDefinitions[id.toString()] },
		getBlockModel(id) { return blockModels[id.toString()] },
		getTextureUV(id) { return textureAtlas.getTextureUV(id) },
		getTextureAtlas() { return textureAtlas.getTextureAtlas() },
		getPixelSize() { return textureAtlas.getPixelSize() },
		getBlockFlags() { return { opaque: false } },
		getBlockProperties() { return null },
		getDefaultBlockProperties() { return null },
	}
	return resources
})

resourcesPromise.then(() => {
	setStatus('')
	dropzone.querySelector('p')!.textContent = 'Drop a .nbt structure file here'
}).catch(err => {
	console.error(err)
	setStatus('Failed to load block resources. Check your connection and reload.', true)
})

// === Orbit camera controls ===

class OrbitCamera {
	private xRotation = 0.8
	private yRotation = 0.5
	private viewDist: number
	private readonly onRender: (view: mat4) => void
	private center: [number, number, number]
	private playerPosition: [number, number, number]

	constructor(
		el: HTMLElement,
		onRender: (view: mat4) => void,
		center: [number, number, number] = [0, 0, 0],
		viewDist = 10,
	) {
		this.onRender = onRender
		this.center = center
		this.viewDist = viewDist
		this.playerPosition = [center[0], center[1] + 1.6, center[2] + viewDist]
		let dragPos: [number, number] | null = null

		el.addEventListener('mousedown', evt => {
			if (evt.button === 0) {
				dragPos = [evt.clientX, evt.clientY]
			}
		})
		window.addEventListener('mousemove', evt => {
			if (dragPos) {
				const dx = evt.clientX - dragPos[0]
				const dy = evt.clientY - dragPos[1]
				if (playerModeToggle.checked) {
					this.yRotation -= dx / 100
					this.xRotation -= dy / 100
				} else {
					this.yRotation += dx / 100
					this.xRotation += dy / 100
				}
				dragPos = [evt.clientX, evt.clientY]
				this.redraw()
			}
		})
		window.addEventListener('mouseup', () => {
			dragPos = null
		})
		el.addEventListener('wheel', evt => {
			evt.preventDefault()
			this.viewDist += evt.deltaY / 100
			this.redraw()
		}, { passive: false })

		let touchPos: [number, number] | null = null
		let pinchDist: number | null = null
		el.addEventListener('touchstart', evt => {
			if (evt.touches.length === 1) {
				touchPos = [evt.touches[0].clientX, evt.touches[0].clientY]
			} else if (evt.touches.length === 2) {
				pinchDist = this.touchDistance(evt.touches)
			}
		}, { passive: true })
		el.addEventListener('touchmove', evt => {
			if (evt.touches.length === 1 && touchPos) {
				evt.preventDefault()
				const dx = evt.touches[0].clientX - touchPos[0]
				const dy = evt.touches[0].clientY - touchPos[1]
				if (playerModeToggle.checked) {
					this.yRotation -= dx / 100
					this.xRotation -= dy / 100
				} else {
					this.yRotation += dx / 100
					this.xRotation += dy / 100
				}
				touchPos = [evt.touches[0].clientX, evt.touches[0].clientY]
				this.redraw()
			} else if (evt.touches.length === 2 && pinchDist !== null) {
				evt.preventDefault()
				const dist = this.touchDistance(evt.touches)
				this.viewDist -= (dist - pinchDist) / 20
				pinchDist = dist
				this.redraw()
			}
		}, { passive: false })
		el.addEventListener('touchend', () => {
			touchPos = null
			pinchDist = null
		})

		const pressedKeys = new Set<string>()
		let movementFrame: number | null = null

		const isViewportActive = () => el.matches(':hover') || document.activeElement === el

		window.addEventListener('keydown', evt => {
			const key = evt.code === 'Space'
				? 'space'
				: evt.key.toLowerCase()
			const allowedKeys = playerModeToggle.checked
				? ['w', 'a', 's', 'd', 'shift', 'control', 'space']
				: ['w', 'a', 's', 'd']
			if (!isViewportActive() || !allowedKeys.includes(key)) return
			evt.preventDefault()
			pressedKeys.add(key)
			if (movementFrame === null) {
				const move = () => {
					if (pressedKeys.size === 0) {
						movementFrame = null
						return
					}

					if (!playerModeToggle.checked) {
						const step = 0.025
						if (pressedKeys.has('a')) this.yRotation -= step
						if (pressedKeys.has('d')) this.yRotation += step
						if (pressedKeys.has('w')) this.xRotation -= step
						if (pressedKeys.has('s')) this.xRotation += step
						this.xRotation = Math.max(-Math.PI / 2, Math.min(Math.PI / 2, this.xRotation))
					} else {
						const step = 0.12
						const forwardX = -Math.sin(this.yRotation)
						const forwardZ = -Math.cos(this.yRotation)
						const rightX = Math.cos(this.yRotation)
						const rightZ = -Math.sin(this.yRotation)
						let dx = 0
						let dz = 0
						if (pressedKeys.has('w')) { dx += forwardX; dz += forwardZ }
						if (pressedKeys.has('s')) { dx -= forwardX; dz -= forwardZ }
						if (pressedKeys.has('d')) { dx += rightX; dz += rightZ }
						if (pressedKeys.has('a')) { dx -= rightX; dz -= rightZ }
						this.playerPosition[0] += dx * step
						this.playerPosition[2] += dz * step
						if (pressedKeys.has('space')) this.playerPosition[1] += step
						if (pressedKeys.has('shift') || pressedKeys.has('control')) this.playerPosition[1] -= step
					}

					this.redraw()
					movementFrame = requestAnimationFrame(move)
				}
				movementFrame = requestAnimationFrame(move)
			}
		})

		window.addEventListener('keyup', evt => {
			const key = evt.code === 'Space' ? 'space' : evt.key.toLowerCase()
			pressedKeys.delete(key)
		})
		window.addEventListener('blur', () => pressedKeys.clear())

		playerModeToggle.addEventListener('change', () => {
			pressedKeys.clear()
			if (playerModeToggle.checked) {
				this.resetForMovementMode()
			} else {
				this.yRotation = 0.5
				this.xRotation = 0.8
				this.center = [...this.center]
			}
			this.redraw()
		})
	}

	private touchDistance(touches: TouchList) {
		const dx = touches[0].clientX - touches[1].clientX
		const dy = touches[0].clientY - touches[1].clientY
		return Math.sqrt(dx * dx + dy * dy)
	}

	public setCenter(center: [number, number, number], viewDist: number) {
		this.center = center
		this.viewDist = viewDist
		this.playerPosition = [center[0], center[1] + 1.6, center[2] + viewDist]
		this.redraw()
	}

	public resetForMovementMode() {
		const horizontalDistance = Math.cos(this.xRotation) * this.viewDist
		this.playerPosition = [
			this.center[0] + Math.sin(this.yRotation) * horizontalDistance,
			this.center[1] + 1.6 + Math.sin(this.xRotation) * this.viewDist,
			this.center[2] + Math.cos(this.yRotation) * horizontalDistance,
		]
		this.redraw()
	}

	public redraw() {
		requestAnimationFrame(() => this.renderImmediately())
	}

	private renderImmediately() {
		this.yRotation = this.yRotation % (Math.PI * 2)
		this.xRotation = Math.max(-Math.PI / 2, Math.min(Math.PI / 2, this.xRotation))
		this.viewDist = Math.max(1, this.viewDist)

		const view = mat4.create()
		if (playerModeToggle.checked) {
			mat4.rotate(view, view, -this.xRotation, [1, 0, 0])
			mat4.rotate(view, view, -this.yRotation, [0, 1, 0])
			mat4.translate(view, view, [-this.playerPosition[0], -this.playerPosition[1], -this.playerPosition[2]])
			this.onRender(view)
			return
		}
		mat4.translate(view, view, [0, 0, -this.viewDist])
		mat4.rotate(view, view, this.xRotation, [1, 0, 0])
		mat4.rotate(view, view, this.yRotation, [0, 1, 0])
		mat4.translate(view, view, [-this.center[0], -this.center[1], -this.center[2]])

		this.onRender(view)
	}
}

// === NBT structure loading ===

function structureFromNbt(root: NbtCompound) {
	if (root.getList('palette').length === 0 && root.getList('palettes').length > 0) {
		const firstPalette = root.getList('palettes', NbtType.List).getList(0, NbtType.Compound)
		root.set('palette', firstPalette)
	}
	return Structure.fromNbt(root)
}

let renderer: StructureRenderer | null = null
let camera: OrbitCamera | null = null
let loadedStructureBytes: Uint8Array | null = null
let loadedFileBaseName = ''
let pendingStructureFile: File | null = null

let structureIdManuallySet = false
let buildNameManuallySet = false

function sanitizeResourceName(input: string): string {
	const sanitized = input
		.trim()
		.toLowerCase()
		.replace(/\.[^.]*$/, '')
		.replace(/[^a-z0-9/._-]+/g, '_')
		.replace(/^_+|_+$/g, '')
	return sanitized || 'structure'
}

function titleCaseResourceName(value: string): string {
	return value
		.replace(/[_-]+/g, ' ')
		.replace(/\b\w/g, letter => letter.toUpperCase())
}

function derivedStructureId(): string {
	return sanitizeResourceName(datapackNameInput.value || loadedFileBaseName)
}

function derivedBuildName(): string {
	return titleCaseResourceName(datapackNameInput.value || loadedFileBaseName)
}

function syncDerivedFields() {
	if (!structureIdManuallySet) structureIdInput.value = derivedStructureId()
	if (!buildNameManuallySet) buildNameInput.value = derivedBuildName()
}

function resizeCanvas() {
	const dpr = window.devicePixelRatio || 1
	const width = Math.max(1, Math.round(viewport.clientWidth * dpr))
	const height = Math.max(1, Math.round(viewport.clientHeight * dpr))
	if (canvas.width !== width || canvas.height !== height) {
		canvas.width = width
		canvas.height = height
	}
	renderer?.setViewport(0, 0, width, height)
	camera?.redraw()
}

async function loadStructure(file: File) {
	setStatus(`Loading ${file.name}…`)
	try {
		const resources = await resourcesPromise
		const buffer = await file.arrayBuffer()
		const bytes = new Uint8Array(buffer)
		const nbtFile = NbtFile.read(bytes)
		const structure = structureFromNbt(nbtFile.root)
		const size = structure.getSize()

		if (!renderer) {
			renderer = new StructureRenderer(gl!, structure, resources)
		} else {
			renderer.setStructure(structure)
		}

		const center: [number, number, number] = [size[0] / 2, size[1] / 2, size[2] / 2]
		const viewDist = Math.max(4, Math.hypot(size[0], size[1], size[2]))

		if (!camera) {
			camera = new OrbitCamera(viewport, view => {
				if (!renderer) return
				gl!.clear(gl!.COLOR_BUFFER_BIT | gl!.DEPTH_BUFFER_BIT)
				renderer.drawStructure(view)
				if (gridToggle.checked) {
					renderer.drawGrid(view)
				}
				if (invisibleToggle.checked) {
					renderer.drawInvisibleBlocks(view)
				}
			}, center, viewDist)
		} else {
			camera.setCenter(center, viewDist)
		}

		resizeCanvas()
		camera.redraw()

		dropzone.style.display = 'none'
		setStatus('')

		loadedStructureBytes = bytes
		loadedFileBaseName = sanitizeResourceName(file.name)
		if (!datapackNameInput.value.trim()) {
			datapackNameInput.value = loadedFileBaseName
		}
		if (!structureIdInput.value.trim()) {
			structureIdInput.value = loadedFileBaseName
		}
		if (!buildNameInput.value.trim()) {
			buildNameInput.value = loadedFileBaseName
				.replace(/[_-]+/g, ' ')
				.replace(/\b\w/g, letter => letter.toUpperCase())
		}
		downloadBtn.disabled = false
		syncDerivedFields()
		pendingFileNameEl.textContent = ''
		previewBtn.disabled = true
		dropzone.classList.remove('structure-selected')
	} catch (err) {
		console.error(err)
		setStatus(`Could not load "${file.name}": ${err instanceof Error ? err.message : err}`, true)
	}
}

async function setPendingStructure(file: File) {
	pendingStructureFile = file
	loadedStructureBytes = null
	previewBtn.disabled = false
	renderer = null
	camera = null
	gl!.clear(gl!.COLOR_BUFFER_BIT | gl!.DEPTH_BUFFER_BIT)
	dropzone.style.display = 'flex'
	dropzone.classList.add('structure-selected')
	fileInput.value = ''

	loadedFileBaseName = sanitizeResourceName(file.name)
	if (!datapackNameInput.value.trim()) datapackNameInput.value = loadedFileBaseName
	syncDerivedFields()

	pendingFileNameEl.textContent = file.name
}

function previewStructure() {
	if (!pendingStructureFile) return
	loadStructure(pendingStructureFile)
}

previewBtn.addEventListener('click', previewStructure)

async function downloadDatapack() {
	if (!validateAllIds()) {
		setStatus('Fix invalid resource locations before downloading.', true)
		const invalidInput = document.querySelector<HTMLInputElement>('#datapack-form .invalid')
		invalidInput?.focus()
		return
	}

	if (!pendingStructureFile && !loadedStructureBytes) return
	if (!loadedStructureBytes && pendingStructureFile) {
		loadedStructureBytes = new Uint8Array(await pendingStructureFile.arrayBuffer())
	}
	if (!loadedStructureBytes) return

	const namespace = sanitizeResourceName(namespaceInput.value || 'examplenamespace').replace(/\./g, '_')
	const structureId = sanitizeResourceName(structureIdInput.value || loadedFileBaseName)
	const buildName = buildNameInput.value.trim() || loadedFileBaseName
		.replace(/[_-]+/g, ' ')
		.replace(/\b\w/g, letter => letter.toUpperCase())
	const recipeId = `${namespace}:${structureId}`
	const creator = creatorInput.value.trim()
	const datapackName = sanitizeResourceName(datapackNameInput.value || loadedFileBaseName)
	const description = datapackDescriptionInput.value.trim() || `Structure "${buildName}"`
	const templateId = `${namespace}:${structureId}`

	const packMcmeta = {
		pack: {
			description,
			pack_format: 9,
			'forge:resource_pack_format': 8,
			'forge:data_pack_format': 9,
		},
	}

	const templateConfig = {
		keys: [
			{
				id: templateId,
				name: buildName,
				'1.0': {
					type: 'structure',
					path: `${namespace}:structures/${structureId}.nbt`,
				},
			},
		],
	}

	const recipeEntry: Record<string, unknown> = {
		id: recipeId,
		output: {
			AMOUNT: 1,
			ITEM: 'the_vault:overworld_inscription',
			NBT: (() => {
				const hexColor = normalizeHexColor(titleColorInput.value) || '#2F96C8'
				const decimalColor = parseInt(hexColor.slice(1), 16)
				return `{structureId:"${templateId}",model:0,color:${decimalColor},display:{Name:'{\"text\":\"${buildName}\",\"color\":\"${hexColor}\"}'}}`
			})(),
		},
		inputs: getRecipeInputs(),
	}
	if (creator) recipeEntry.creator = creator

	const recipeConfig = {
		overworldInscriptionRecipes: [recipeEntry],
	}

	const zipped = zipSync({
		'pack.mcmeta': strToU8(JSON.stringify(packMcmeta, null, 2)),
		[`data/${namespace}/structures/${structureId}.nbt`]: loadedStructureBytes,
		[`data/${namespace}/vault_configs/templates/${structureId}_template.json`]: strToU8(JSON.stringify(templateConfig, null, 2)),
		[`data/${namespace}/vault_configs/vault_recipes/overworld_inscription/${structureId}_recipe.json`]: strToU8(JSON.stringify(recipeConfig, null, 2)),
	})

	const blob = new Blob([zipped], { type: 'application/zip' })
	const url = URL.createObjectURL(blob)
	const a = document.createElement('a')
	a.href = url
	a.download = `${datapackName}.zip`
	a.click()
	URL.revokeObjectURL(url)
}

downloadBtn.addEventListener('click', downloadDatapack)

fileInput.addEventListener('change', () => {
	const file = fileInput.files?.[0]
	if (file) setPendingStructure(file)
})

for (const evt of ['dragenter', 'dragover']) {
	viewport.addEventListener(evt, e => {
		e.preventDefault()
		dropzone.classList.add('drag-over')
	})
}
for (const evt of ['dragleave', 'drop']) {
	viewport.addEventListener(evt, e => {
		e.preventDefault()
		dropzone.classList.remove('drag-over')
	})
}
viewport.addEventListener('drop', e => {
	const file = e.dataTransfer?.files?.[0]
	if (file) setPendingStructure(file)
})

gridToggle.addEventListener('change', () => camera?.redraw())
invisibleToggle.addEventListener('change', () => camera?.redraw())

window.addEventListener('resize', resizeCanvas)
resizeCanvas()

function normalizeHexColor(value: string): string | null {
	const match = value.trim().match(/^#?([0-9a-f]{6})$/i)
	return match ? `#${match[1].toUpperCase()}` : null
}

function updateColorPreview() {
	const cssColor = normalizeHexColor(titleColorInput.value)
	if (cssColor) {
		titleColorInput.value = cssColor
		titleColorInput.style.color = cssColor
	}
}

titleColorInput.addEventListener('input', updateColorPreview)
updateColorPreview()

// Ingredient list functionality
function createIngredientRow(amount = 1, item = '') {
	const row = document.createElement('div')
	row.className = 'ingredient-row'
	row.innerHTML = `
		<input class="ingredient-amount" type="text" inputmode="numeric" maxlength="5" aria-label="Ingredient amount" />
		<input class="ingredient-item" type="text" aria-label="Ingredient item ID" />
		<button class="ingredient-delete" type="button" aria-label="Delete ingredient">Delete</button>
	`
	const amountInput = row.querySelector('.ingredient-amount') as HTMLInputElement
	const itemInput = row.querySelector('.ingredient-item') as HTMLInputElement
	amountInput.value = String(amount)
	itemInput.value = item
	row.querySelector('.ingredient-delete')!.addEventListener('click', () => row.remove())
	ingredientList.append(row)
}

addIngredientButton.addEventListener('click', () => createIngredientRow())

ingredientList.querySelectorAll('.ingredient-row').forEach(row => {
	row.querySelector('.ingredient-delete')!.addEventListener('click', () => row.remove())
	const itemInput = row.querySelector<HTMLInputElement>('.ingredient-item')
	if (itemInput) {
		itemInput.addEventListener('input', () => validateIngredientItem(itemInput))
		itemInput.addEventListener('change', () => validateIngredientItem(itemInput))
	}
})

// Recipe inputs and validation
function getRecipeInputs() {
	return Array.from(ingredientList.querySelectorAll('.ingredient-row')).map(row => {
		const amountInput = row.querySelector('.ingredient-amount') as HTMLInputElement
		const itemInput = row.querySelector('.ingredient-item') as HTMLInputElement
		return {
			AMOUNT: Math.max(0, parseInt(amountInput.value.trim()) || 0),
			ITEM: itemInput.value.trim(),
			NBT: '{}',
		}
	}).filter(input => input.ITEM)
}

const MINECRAFT_NAMESPACE_REGEX = /^[a-z0-9_.-]+$/
const MINECRAFT_PATH_REGEX = /^[a-z0-9/._-]+$/
let validItemIds = new Set<string>()

function setInputValidity(input: HTMLInputElement, valid: boolean, message: string) {
	input.setCustomValidity(valid ? '' : message)
	input.classList.toggle('invalid', !valid)
	input.classList.remove('warning')
	input.setAttribute('aria-invalid', String(!valid))
}

function validateNamespace(input: HTMLInputElement) {
	setInputValidity(input, MINECRAFT_NAMESPACE_REGEX.test(input.value.trim()), 'Use lowercase letters, numbers, underscore, dot, or hyphen.')
}

function validatePathId(input: HTMLInputElement, allowSlash = true) {
	const value = input.value.trim()
	const regex = allowSlash ? MINECRAFT_PATH_REGEX : /^[a-z0-9_.-]+$/
	setInputValidity(input, regex.test(value), 'Use lowercase letters, numbers, underscore, dot, or hyphen.')
}

function validateIngredientItem(input: HTMLInputElement) {
	const value = input.value.trim()
	const parts = value.split(':')
	const syntacticallyValid = parts.length === 2
		&& MINECRAFT_NAMESPACE_REGEX.test(parts[0])
		&& MINECRAFT_PATH_REGEX.test(parts[1])

	if (!syntacticallyValid) {
		setInputValidity(input, false, 'Use a resource location like namespace:item_name.')
		input.removeAttribute('title')
		return
	}

	input.setCustomValidity('')
	input.classList.remove('invalid')
	input.setAttribute('aria-invalid', 'false')
	const known = validItemIds.has(value)
	input.classList.toggle('warning', !known)
	if (known) input.removeAttribute('title')
	else input.title = 'This item ID is not in the temporary known-item list. It may come from another mod.'
}

function validateAllIds(): boolean {
	validateNamespace(namespaceInput)
	validatePathId(structureIdInput, false)
	for (const input of ingredientList.querySelectorAll<HTMLInputElement>('.ingredient-item')) {
		validateIngredientItem(input)
	}
	return !document.querySelector('#datapack-form .invalid')
}

namespaceInput.addEventListener('input', () => validateNamespace(namespaceInput))
structureIdInput.addEventListener('input', () => {
	structureIdManuallySet = structureIdInput.value.trim() !== ''
		&& structureIdInput.value.trim() !== derivedStructureId()
	validatePathId(structureIdInput, false)
})
buildNameInput.addEventListener('input', () => {
	buildNameManuallySet = buildNameInput.value.trim() !== ''
		&& buildNameInput.value.trim() !== derivedBuildName()
})
ingredientList.addEventListener('input', event => {
	const input = event.target
	if (input instanceof HTMLInputElement && input.classList.contains('ingredient-item')) {
		validateIngredientItem(input)
	}
})

fetch('/valid-item-ids.json')
	.then(response => response.json())
	.then((catalog: { items?: string[] }) => {
		validItemIds = new Set(catalog.items ?? [])
		for (const input of ingredientList.querySelectorAll<HTMLInputElement>('.ingredient-item')) {
			validateIngredientItem(input)
		}
	})
	.catch(error => console.warn('Could not load valid item IDs:', error))
